package local.tvmorph.tv;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;
/** Fullscreen, local content-URI player. IPTV playback remains separate. */
public final class UsbPlayerActivity extends Activity{
 private VideoView video;private MediaController controls;private boolean resume;
 private String t(String ar,String en){return UiSettings.text(this,ar,en);}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);Uri uri=getIntent().getData();if(uri==null||!"content".equals(uri.getScheme())){finish();return;}FrameLayout root=new FrameLayout(this);root.setBackgroundColor(0xff000000);video=new VideoView(this);FrameLayout.LayoutParams size=new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER);root.addView(video,size);setContentView(root);controls=new MediaController(this);controls.setAnchorView(video);android.graphics.drawable.GradientDrawable glass=new android.graphics.drawable.GradientDrawable();glass.setColor(UiSettings.color(this,"uiSurface",0xee142036));glass.setCornerRadius(20*getResources().getDisplayMetrics().density);glass.setStroke(2,UiSettings.color(this,"uiAccent",0xff63caff));controls.setBackground(glass);video.setMediaController(controls);video.setOnPreparedListener(mp->{video.start();controls.show(video.isPlaying()?4000:0);video.requestFocus();});video.setOnCompletionListener(mp->{controls.show(video.isPlaying()?4000:0);});video.setOnErrorListener((mp,what,extra)->{new AlertDialog.Builder(this).setTitle(t("تعذّر تشغيل الملف","Unable to play file")).setMessage(t("ترميز الملف قد لا يكون مدعومًا بهذا المشغّل. جرّب مشغّلًا مثبتًا آخر.","The file codec may not be supported by this player. Try another installed player.")).setPositiveButton(t("مشغّل آخر","Other player"),(d,w)->external()).setNegativeButton(t("رجوع","Back"),(d,w)->finish()).setOnCancelListener(d->finish()).show();return true;});video.setVideoURI(uri);}
 private void external(){try{Intent view=new Intent(Intent.ACTION_VIEW).setDataAndType(getIntent().getData(),getIntent().getStringExtra("mime")).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);view.setClipData(ClipData.newRawUri("USB video",getIntent().getData()));startActivity(Intent.createChooser(view,t("اختيار مشغّل","Choose player")));finish();}catch(RuntimeException e){Toast.makeText(this,t("لا يوجد مشغّل متوافق مثبت.","No compatible player is installed."),Toast.LENGTH_LONG).show();}}
 @Override public boolean onKeyDown(int key,android.view.KeyEvent e){if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(!controls.isShowing()){controls.show(video.isPlaying()?4000:0);return true;}if(video.isPlaying())video.pause();else video.start();controls.show(video.isPlaying()?4000:0);return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){int target=video.getCurrentPosition()+(key==KeyEvent.KEYCODE_DPAD_RIGHT?10000:-10000);video.seekTo(Math.max(0,Math.min(Math.max(0,video.getDuration()-100),target)));controls.show(video.isPlaying()?4000:0);return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){controls.show(video.isPlaying()?4000:0);}return super.onKeyDown(key,e);}
 @Override protected void onPause(){resume=video!=null&&video.isPlaying();if(video!=null)video.pause();super.onPause();}
 @Override protected void onResume(){super.onResume();if(video!=null&&resume)video.start();}
 @Override protected void onDestroy(){if(video!=null)video.stopPlayback();if(controls!=null)controls.hide();super.onDestroy();}
}
